actions.script:
import org.moqui.context.ExecutionContext
ExecutionContext ec = context.ec
def fromD = (fromDate ?: ec.l10n.format(ec.user.nowTimestamp, 'yyyy-MM-dd'))
def thruD = (thruDate ?: fromD)
def ds = java.sql.Timestamp.valueOf(fromD + ' 00:00:00')
def de = java.sql.Timestamp.valueOf(thruD + ' 23:59:59')
def _org = ec.user.getPreference("ACTIVE_ORGANIZATION")
def f = ec.entity.find("zenith.erp.pos.PosAmendmentView")
    .condition("amendmentDate","greater-equals",ds).condition("amendmentDate","less-equals",de)
if (_org && _org != '_NA_') f.condition("organizationPartyId", _org)
def ams = f.orderBy("amendmentDate").list()
def ctLabel = { ct -> [PRICE_CHANGE:'Item Price', QTY_CHANGE:'Item Qty', DISCOUNT_CHANGE:'Discount', ITEM_ADDED:'Item Added', ITEM_REMOVED:'Item Removed', TAX_CHANGE:'Tax'].get(ct) ?: (ct ?: '') }
def billMap = new LinkedHashMap()
ams.each { a -> def tid = a.transactionId; def b = billMap[tid]
    if (b == null) { b = [billNo:(a.transactionNumber ?: tid), firstBefore:(a.oldGrandTotal != null ? (a.oldGrandTotal as BigDecimal) : null), lastAfter:null, editsMade:0, lastDate:null, editId:null, editedBy:null, terminal:null, reason:null]; billMap[tid] = b }
    b.editsMade++; if (b.firstBefore == null && a.oldGrandTotal != null) b.firstBefore = a.oldGrandTotal as BigDecimal
    if (a.newGrandTotal != null) b.lastAfter = a.newGrandTotal as BigDecimal
    b.lastDate = a.amendmentDate; b.editId = a.amendmentId
    def nm = "${a.firstName ?: ''} ${a.lastName ?: ''}".toString().trim(); b.editedBy = nm ?: (a.amendedByPartyId ?: '')
    b.terminal = a.terminalName ?: ''; b.reason = (a.reason && a.reason.trim()) ? a.reason.trim() : ctLabel(a.changeType) }
def rows = billMap.values().toList().sort { -(it.lastDate ? it.lastDate.getTime() : 0L) }
def st = (searchText ?: '').trim().toLowerCase()
if (st) rows = rows.findAll { [it.billNo, it.editedBy, it.reason, it.terminal].collect { (it ?: '').toString().toLowerCase() }.any { it.contains(st) } }
def esc = { v -> if (v == null) return ""; String s = v.toString().trim(); (s.contains(",")||s.contains("\"")||s.contains("\n")) ? "\"" + s.replace("\"","\"\"") + "\"" : s }
def num = { v -> String.format("%.2f", (v ?: 0.0) as double) }
def dt = { v -> v == null ? "" : ec.l10n.format(v, 'yyyy-MM-dd hh:mm a') }
StringBuilder csv = new StringBuilder()
csv.append("ZetaERP - Edited Bills Report\n")
csv.append("Period: ${fromD} to ${thruD}  |  Generated: ${ec.l10n.format(ec.user.nowTimestamp, 'dd MMM yyyy HH:mm')}\n\n")
csv.append("Edit ID,Bill No,Original Bill No,Edit Date & Time,Edited By,Terminal,Edits Made,Amount Before,Amount After,Difference,Reason,Status\n")
rows.each { b -> def diff = (b.lastAfter ?: 0G) - (b.firstBefore ?: 0G)
    csv.append([esc(b.editId), esc(b.billNo), esc(b.billNo), esc(dt(b.lastDate)), esc(b.editedBy), esc(b.terminal), b.editsMade, num(b.firstBefore), num(b.lastAfter), ((diff>=0G?'+':'-')+num(diff.abs())), esc(b.reason), "Completed"].join(",")).append("\n") }
ec.web.sendTextResponse(csv.toString(), "text/csv", "Edited_Bills_${ec.l10n.format(ec.user.nowTimestamp, 'yyyyMMdd_HHmm')}.csv")

def zinr = context.zinr
def _org = ec.user.getPreference("ACTIVE_ORGANIZATION")
def f = ec.entity.find("zenith.erp.pos.PosAmendmentView")
    .condition("amendmentDate", "greater-equals", dayStart)
    .condition("amendmentDate", "less-equals", dayEnd)
if (_org && _org != '_NA_') f.condition("organizationPartyId", _org)
def ams = f.orderBy("amendmentDate").list()
def ctLabel = { ct -> [PRICE_CHANGE:'Item Price', QTY_CHANGE:'Item Qty', DISCOUNT_CHANGE:'Discount', ITEM_ADDED:'Item Added', ITEM_REMOVED:'Item Removed', TAX_CHANGE:'Tax'].get(ct) ?: (ct ?: '—') }
def billMap = new LinkedHashMap()
def userSet = new LinkedHashSet()
ams.each { a ->
    if (a.amendedByPartyId) userSet.add(a.amendedByPartyId)
    def tid = a.transactionId; def b = billMap[tid]
    if (b == null) { b = [transactionId:tid, billNo:(a.transactionNumber ?: tid), firstBefore:(a.oldGrandTotal != null ? (a.oldGrandTotal as BigDecimal) : null), lastAfter:null, editsMade:0, lastDate:null, editId:null, editedBy:null, terminal:null, reason:null]; billMap[tid] = b }
    b.editsMade++
    if (b.firstBefore == null && a.oldGrandTotal != null) b.firstBefore = a.oldGrandTotal as BigDecimal
    if (a.newGrandTotal != null) b.lastAfter = a.newGrandTotal as BigDecimal
    b.lastDate = a.amendmentDate; b.editId = a.amendmentId
    def nm = "${a.firstName ?: ''} ${a.lastName ?: ''}".toString().trim(); b.editedBy = nm ?: (a.amendedByPartyId ?: '—')
    b.terminal = a.terminalName ?: '—'
    b.reason = (a.reason && a.reason.trim()) ? a.reason.trim() : ctLabel(a.changeType)
}
def rows = billMap.values().toList().sort { -(it.lastDate ? it.lastDate.getTime() : 0L) }
def st = (searchText ?: '').trim().toLowerCase()
if (st) rows = rows.findAll { [it.billNo, it.editedBy, it.reason, it.terminal].collect { (it ?: '').toString().toLowerCase() }.any { it.contains(st) } }
editedBillsList = rows

// ---- KPI totals ----
statTotalEdits = ams.size()
statBillsAffected = billMap.size()
def sumBefore = rows.inject(0.0G) { acc, it -> acc + (it.firstBefore ?: 0.0G) }
def sumAfter  = rows.inject(0.0G) { acc, it -> acc + (it.lastAfter ?: 0.0G) }
statAmountBeforeStr = '₹ ' + zinr.inr(ec.l10n.format(sumBefore, '#,##0.00'))
statAmountAfterStr  = '₹ ' + zinr.inr(ec.l10n.format(sumAfter, '#,##0.00'))
statDifferenceStr   = '₹ ' + zinr.inr(ec.l10n.format((sumBefore - sumAfter).abs(), '#,##0.00'))
statEditedByUsers = userSet.size()
